def predict(board, action):
    if action[0] == 'MOUSE' and action[1] == 3 and action[2] == 27:
        row, col = action[1], action[2]
        new_board = [list(row) for row in board]
        target_char = new_board[row][col]
        if target_char == 'N':
            for i in range(max(0, row-1), min(63, row+2)):
                for j in range(max(0, col-1), min(63, col+2)):
                    if new_board[i][j] == 'S':
                        new_board[i][j] = 'N'
                        new_board[row][col] = 'S'
                        break
        elif target_char == 'B' or target_char == 'G':
            for i in range(max(0, row-1), min(63, row+2)):
                for j in range(max(0, col-1), min(63, col+2)):
                    if new_board[i][j] in ['S', 'N']:
                        new_board[i][j] = target_char
                        new_board[row][col] = 'S'
                        break
        elif target_char == 'W':
            new_board[row][col] = 'p'
        else:
            new_board[row][col] = 'S'
        return [''.join(row) for row in new_board]
    return board
